// spec: specs/talent-onboarding.md §3.5 · case: .qa/tests/talent-onboarding/TO-3-5.md
// API only (no page, no login): the CV bucket must not be readable by a public / unsigned URL.
import { test, expect } from '@playwright/test';
import * as fs from 'fs';
import path from 'path';

// Supabase project ref from the auth cookie name `sb-<ref>-auth-token` (same env as the saved talent session).
function supabaseHost(): string {
  const state = JSON.parse(fs.readFileSync(path.join(__dirname, '../../../auth/talent.json'), 'utf8'));
  const cookie = (state.cookies as { name: string }[]).find((c) => /^sb-[a-z0-9]+-auth-token/.test(c.name));
  if (!cookie) throw new Error('No sb-<ref>-auth-token cookie in auth/talent.json — run npm run qa-login');
  const ref = cookie.name.match(/^sb-([a-z0-9]+)-auth-token/)![1];
  return `https://${ref}.supabase.co`;
}

test.describe('Talent CV upload — storage privacy', () => {
  test('CV bucket has no public URL @desktop @prod-safe #1866b9', async ({ request }) => {
    const host = supabaseHost();
    const probe = 'QA-AUTO-probe/cv.pdf';

    const pub = await request.get(`${host}/storage/v1/object/public/documents/${probe}`);
    expect(pub.status()).not.toBe(200);
    expect(await pub.text()).toContain('Bucket not found');

    const unsigned = await request.get(`${host}/storage/v1/object/sign/documents/${probe}`);
    expect(unsigned.status()).not.toBe(200);
  });
});
